-- Authentication and isolation checks; every synthetic record is rolled back.
begin;
create temporary table growth_ctx(key text primary key,id uuid not null default gen_random_uuid());
insert into growth_ctx(key) values('owner'),('manager'),('coach'),('other_coach'),('member'),('parent'),('org'),('other_org'),('referral');
grant select on growth_ctx to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) select id,'referral-growth-'||id||'@example.invalid',now(),false from growth_ctx where key in ('owner','manager','coach','other_coach','member','parent');
insert into public.staff_members(user_id,role,active) select id,case when key in ('coach','other_coach') then 'coach' else key end,true from growth_ctx where key in ('owner','manager','coach','other_coach');
insert into public.star_organisations(id,name,kind,created_by,referral_assignee) select id,'Synthetic referral growth '||key,'school',(select id from growth_ctx where key='manager'),(select id from growth_ctx where key='coach') from growth_ctx where key in ('org','other_org');
insert into public.star_organisation_members(organisation_id,email,display_name,invited_by) values((select id from growth_ctx where key='org'),'referral-growth-'||(select id from growth_ctx where key='member')||'@example.invalid','Synthetic member',(select id from growth_ctx where key='manager'));
create function pg_temp.growth_assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Growth check failed: %',message; end if; end$$;
create function pg_temp.growth_denied(action text,data jsonb default '{}') returns void language plpgsql as $$begin begin perform public.star_organisation_portal(action,data); exception when others then return; end; raise exception 'Unexpected growth access: %',action; end$$;
-- Branding RPC is intentionally callable by anonymous readers, with no identity or contact data.
create temporary table growth_codes as select id,referral_code from public.star_organisations where id in (select id from growth_ctx where key in ('org','other_org'));
grant select on growth_codes to anon,authenticated;
set local role anon;
select pg_temp.growth_assert((public.star_organisation_referral_page((select referral_code from growth_codes where id=(select id from growth_ctx where key='org')))->>'name') like 'Synthetic referral growth%','anonymous branding page works');
select pg_temp.growth_assert(not (public.star_organisation_referral_page((select referral_code from growth_codes limit 1)) ?| array['id','created_by','referral_assignee','guardian_email','players']),'public projection contains branding only');
select pg_temp.growth_denied('referral_tasks');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='manager'),true);
select public.star_organisation_portal('save_branding',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org'),'brand_colour','#006b5a','logo_path','','welcome_text','Welcome from our school','referral_assignee',(select id from growth_ctx where key='coach')));
select pg_temp.growth_denied('save_branding',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org'),'brand_colour','#006b5a','logo_path','someone-elses/logo.png','referral_assignee',(select id from growth_ctx where key='coach')));
select pg_temp.growth_denied('save_branding',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org'),'brand_colour','bad colour','logo_path','','referral_assignee',(select id from growth_ctx where key='coach')));
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='member'),true);
select public.star_organisation_portal('accept');
select pg_temp.growth_denied('save_branding',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org'),'brand_colour','#ffffff','logo_path',''));
select pg_temp.growth_denied('referral_tasks');
select public.star_organisation_portal('referral',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org'),'player_name','Synthetic first referral','age_band','11–13','guardian_name','Synthetic parent','guardian_email','parent@example.invalid','reason','Confidence and receiving the ball','permission',true));
reset role;
update growth_ctx set id=(select id from public.star_organisation_referrals where organisation_id=(select id from growth_ctx where key='org') limit 1) where key='referral';
select pg_temp.growth_assert((select assigned_to=(select id from growth_ctx where key='coach') and contact_due_at=created_at+interval '12 hours' from public.star_organisation_referrals where id=(select id from growth_ctx where key='referral')),'chosen assignee and 12 hour deadline');
select pg_temp.growth_assert(exists(select 1 from public.star_organisation_alerts where recipient_id=(select id from growth_ctx where key='owner') and referral_id=(select id from growth_ctx where key='referral') and kind='new_referral'),'new referral alerts owner');
-- Simulate the deadline passing; no contact is recorded.
update public.star_organisation_referrals set created_at=now()-interval '13 hours',contact_due_at=now()-interval '1 hour' where id=(select id from growth_ctx where key='referral');
select star_private.refresh_org_referral_alerts();
select star_private.refresh_org_referral_alerts();
select pg_temp.growth_assert((select count(*)=1 from public.star_organisation_alerts where recipient_id=(select id from growth_ctx where key='owner') and referral_id=(select id from growth_ctx where key='referral') and kind='overdue'),'overdue owner alert generated once');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='other_coach'),true);
select pg_temp.growth_assert(jsonb_array_length(public.star_organisation_portal('referral_tasks')->'referrals')=0,'unassigned coach sees no referrals');
select pg_temp.growth_denied('record_first_attendance',jsonb_build_object('id',(select id from growth_ctx where key='referral'),'attended_at',now()));
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='member'),true);
select pg_temp.growth_assert(not ((public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org')))->'referrals'->0) ?| array['assigned_to','contact_due_at']),'organisation cannot see internal assignment or task deadline');
select pg_temp.growth_assert((select count(*)=0 from public.star_organisation_alerts),'organisation cannot read staff alerts');
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='coach'),true);
select pg_temp.growth_assert(jsonb_array_length(public.star_organisation_portal('referral_tasks')->'referrals')=1,'assigned coach receives task');
select pg_temp.growth_denied('manage');
-- Use server-provided revision, exactly as the client does.
select public.star_organisation_portal('referral_followup',jsonb_build_object('id',(select id from growth_ctx where key='referral'),'expected_updated_at',public.star_organisation_portal('referral_tasks')->'referrals'->0->>'updated_at','assigned_to',(select id from growth_ctx where key='other_coach'),'status','contacted','response','We have spoken and discussed a first session.','contacted',true));
select pg_temp.growth_assert(jsonb_array_length(public.star_organisation_portal('referral_tasks')->'referrals')=0,'contact completes follow-up task');
reset role;
select pg_temp.growth_assert((select contacted_at is not null and assigned_to=(select id from growth_ctx where key='coach') from public.star_organisation_referrals where id=(select id from growth_ctx where key='referral')),'contact recorded and coach cannot reassign themselves');
create temporary table growth_revision as select id,updated_at from public.star_organisation_referrals where id=(select id from growth_ctx where key='referral');grant select on growth_revision to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='manager'),true);
select pg_temp.growth_denied('record_first_attendance',jsonb_build_object('id',(select id from growth_ctx where key='referral'),'expected_updated_at',(select updated_at from growth_revision),'attended_at',now()+interval '1 hour'));
select pg_temp.growth_denied('referral_followup',jsonb_build_object('id',(select id from growth_ctx where key='referral'),'expected_updated_at','2000-01-01T00:00:00Z','assigned_to',(select id from growth_ctx where key='coach'),'status','reviewing'));
select public.star_organisation_portal('record_first_attendance',jsonb_build_object('id',(select id from growth_ctx where key='referral'),'expected_updated_at',(select updated_at from growth_revision),'attended_at',now()-interval '1 hour'));
select set_config('request.jwt.claim.sub',(select id::text from growth_ctx where key='member'),true);
select pg_temp.growth_assert((public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from growth_ctx where key='org')))->'summary'->>'first_attended')::int=1,'organisation sees attended milestone summary');
select pg_temp.growth_denied('organisation',jsonb_build_object('organisation_id',(select id from growth_ctx where key='other_org')));
reset role;
update public.star_organisations set active=false where id=(select id from growth_ctx where key='org');
set local role anon;
select pg_temp.growth_assert(public.star_organisation_referral_page((select referral_code from growth_codes where id=(select id from growth_ctx where key='org'))) is null,'paused organisation public referral page hidden');
reset role;
rollback;
select 'Referral growth permissions, assignment, milestones, concurrency and alert checks passed; fixtures rolled back.' as result;
